/**
 * Relationship of the insect to garden / cultivated plants. "pest"=Schädling (harms plants), "beneficial"=Nützling (predator or pollinator), "neutral"=Neutral.
 */
export type InsectRelationStatus = typeof InsectRelationStatus[keyof typeof InsectRelationStatus];


export const InsectRelationStatus = {
  pest: 'pest',
  beneficial: 'beneficial',
  neutral: 'neutral',
} as const;

export interface Insect {
  id: number;
  /** German common name (e.g. "Marienkäfer"). */
  germanName: string;
  /** Scientific / Latin name (e.g. "Coccinella septempunctata"). */
  scientificName: string;
  category: InsectCategory;
  relationStatus: InsectRelationStatus;
  /** German names of plants this insect frequently targets or visits. */
  affectedPlants: string[];
  /** German description of appearance, habitat, and behaviour. */
  description: string;
  /** For pests: organic / biological treatment and prevention tips in German. Empty string for beneficial and neutral insects. */
  treatmentTips: string;
  /** German common name of the plant the insect was photographed on, when a host plant was clearly visible. Null otherwise. */
  plantContext?: string | null;
  /** ID of the user who triggered this scan. */
  scannedByUserId?: string | null;
  /** UUID that identifies the photo in the client's local IndexedDB image store. Null for entries created before the local-first migration (those use GET /insects/{id}/image instead). */
  localImageId?: string | null;
  /** AI rating 1-10 of how well the shared photo shows the species. A later scan with a clearly better photo replaces it, unless imageLocked is set. Null for photos never rated. */
  imageQuality?: number | null;
  /** Set by the admin: the shared photo is never replaced automatically. */
  imageLocked?: boolean;
  /** Public https URL of the photo on the image CDN (Cloudinary). Use it directly as an <img> source. Takes priority over localImageId and the legacy image endpoint. */
  imageUrl?: string | null;
  /** Coarse location region where the scan was taken (e.g. "München"). Null when the user did not grant location permission. */
  locationRegion?: string | null;
  createdAt: string;
}

export interface ScanInsectInput {
  /** Base64-encoded data URL of the captured photo (e.g. "data:image/jpeg;base64,..."). Must be an image data URL. The image is used for AI identification only and is NOT stored server-side; use localImageId for local storage reference. */
  image: string;
  /** Client-generated UUID (crypto.randomUUID()) identifying the photo in the device's local IndexedDB image store. */
  localImageId?: string;
  /** Optional coarse location region (e.g. "München"). Same semantics as PlantScanInput.locationRegion. */
  locationRegion?: string;
}

